    # THREAD CONTROLLER
    def download_finished(self):
        if not self.errorflag:
            self.retstatus = 'COMPLETED'
            self.close()

    def define_thread(self):
        self.downloadACTaskThread = downloadACDialogThread.downloadACThread()
        self.downloadACTaskThread.check_dependencies_status.connect(self.check_dependencies_status)
        self.downloadACTaskThread.download_engine_status.connect(self.download_engine_status)
